    private fun part54(): Array<Pair<String, Array<out String>>> = arrayOf(
        "tut_armory54_t" to t("Zbrojownia", "Armory", "Waffenkammer", "Armería", "Armurerie", "Armeria", "Arsenal", "Зброярня", "Wapenkamer", "Cephanelik"),
        "tut_armory54" to t("Masz nadmiar złota albo pełną armię? Dotknij kowadła. Zbrojownia zwiększa zdrowie i obrażenia twoich jednostek.", "Extra gold or a full army? Tap the anvil. The armory increases your troops' health and damage.", "Gold übrig oder Armee voll? Tippe auf den Amboss. Die Waffenkammer erhöht Leben und Schaden deiner Truppen.", "¿Te sobra oro o tienes el ejército lleno? Toca el yunque. La armería aumenta salud y daño de tus tropas.", "Trop d’or ou armée pleine ? Touchez l’enclume. L’armurerie améliore la vie et les dégâts de vos troupes.", "Hai oro in eccesso o l’esercito pieno? Tocca l’incudine. L’armeria aumenta vita e danni delle truppe.", "Tens ouro extra ou o exército cheio? Toca na bigorna. O arsenal aumenta a vida e o dano das tropas.", "Зайве золото чи повне військо? Натисни ковадло. Зброярня підсилює здоров’я та шкоду бійців.", "Goud over of je leger vol? Tik op het aambeeld. De wapenkamer verhoogt gezondheid en schade van troepen.", "Altın fazla mı, ordu dolu mu? Örse dokun. Cephanelik birliklerin canını ve hasarını artırır."),
        "tut_stance54_t" to t("Trzymaj czy Naprzód", "Hold or Advance", "Halten oder Vorwärts", "Mantener o Avanzar", "Tenir ou Avancer", "Tieni o Avanza", "Manter ou Avançar", "Тримати чи Вперед", "Houden of Vooruit", "Tut veya İlerle"),
        "tut_stance54" to t("Wróg naciera. Dotknij przycisku postawy, aby bronić linii (Trzymaj). Ponowne dotknięcie daje rozkaz Naprzód.", "The enemy is closing in. Tap the stance button to Hold your line. Tap again to Advance.", "Der Feind rückt an. Tippe auf die Haltung, um die Linie zu halten. Nochmals tippen: Vorwärts.", "El enemigo se acerca. Toca la postura para mantener la línea. Toca de nuevo para avanzar.", "L’ennemi approche. Touchez la posture pour tenir la ligne. Touchez encore pour avancer.", "Il nemico si avvicina. Tocca la postura per tenere la linea. Tocca ancora per avanzare.", "O inimigo aproxima-se. Toca na postura para manter a linha. Toca de novo para avançar.", "Ворог наступає. Натисни позицію, щоб тримати лінію. Натисни ще раз для наступу.", "De vijand komt eraan. Tik op de houding om de linie te houden. Tik weer om op te rukken.", "Düşman yaklaşıyor. Hattı tutmak için duruşa dokun. İlerlemek için tekrar dokun."),
        "tut_rally54_t" to t("Zryw wojsk", "Troop rally", "Ansturm", "Impulso de tropas", "Élan des troupes", "Slancio delle truppe", "Ímpeto das tropas", "Ривок війська", "Troepenstoot", "Atılım"),
        "tut_rally54" to t("Wróg napiera. Dotknij flagi Zrywu: przez chwilę oddziały poruszają się i atakują szybciej. Zdolność potem się odnawia.", "The enemy is pushing. Tap the rally flag: troops move and attack faster briefly. Then it recharges.", "Der Feind drückt vor. Tippe auf die Flagge: Truppen bewegen sich und greifen kurz schneller an. Dann lädt sie auf.", "El enemigo presiona. Toca la bandera: tus tropas avanzan y atacan más rápido durante un rato. Luego se recarga.", "L’ennemi pousse. Touchez le drapeau : les troupes avancent et attaquent plus vite un instant. La capacité se recharge ensuite.", "Il nemico avanza. Tocca la bandiera: le truppe si muovono e attaccano più in fretta per poco. Poi si ricarica.", "O inimigo avança. Toca na bandeira: as tropas movem-se e atacam mais depressa por pouco tempo. Depois recarrega.", "Ворог тисне. Натисни прапор: бійці ненадовго рухаються й атакують швидше. Потім уміння відновлюється.", "De vijand dringt aan. Tik op de vlag: je troepen bewegen en vallen even sneller aan. Daarna laadt het op.", "Düşman bastırıyor. Bayrağa dokun: birlikler kısa süre hızlı hareket edip saldırır. Sonra yeniden dolar."),
        "tut_barrage54" to t("Dotknij ikony ostrzału, aby ustawić cel na polu bitwy.", "Tap the barrage icon to aim at the battlefield.", "Tippe auf das Beschusssymbol, um ein Ziel zu wählen.", "Toca el icono de bombardeo para apuntar al campo.", "Touchez l’icône de barrage pour viser sur le terrain.", "Tocca l’icona del bombardamento per mirare sul campo.", "Toca no ícone de bombardeamento para apontar no campo.", "Натисни піктограму обстрілу, щоб вибрати ціль.", "Tik op het beschietingspictogram om te richten.", "Hedef seçmek için bombardıman simgesine dokun."),
        "tut_barrage_drag54" to t("Przeciągnij palcem po polu, aby przesunąć znacznik celowania. Potem dotknij wybranego punktu, aby wystrzelić.", "Drag across the field to move the aiming marker. Then tap your chosen spot to fire.", "Wische über das Feld, um die Zielmarkierung zu bewegen. Tippe dann auf die Stelle, um zu feuern.", "Desliza el dedo por el campo para mover la mira. Luego toca el lugar elegido para disparar.", "Glissez le doigt sur le terrain pour déplacer le repère. Touchez ensuite le point visé pour tirer.", "Trascina il dito sul campo per spostare il mirino. Poi tocca il punto scelto per sparare.", "Arrasta o dedo no campo para mover a mira. Depois toca no local escolhido para disparar.", "Проведи пальцем по полю, щоб перемістити приціл. Потім торкнися вибраної точки для пострілу.", "Sleep over het veld om de doelmarkering te verplaatsen. Tik daarna op de gewenste plek om te vuren.", "Nişanı taşımak için parmağını alanda sürükle. Ardından ateş etmek için hedefe dokun."),
        "hint_variant54" to t("Wybierz wariant epoki. Każdy ma inne jednostki i wieże — porównaj opisy przed wyborem.", "Choose an era variant. Units and turrets differ; compare the descriptions first.", "Wähle eine Epochenvariante. Einheiten und Türme unterscheiden sich; vergleiche die Beschreibungen.", "Elige una variante de era. Las tropas y torres son distintas; compara sus descripciones.", "Choisissez une variante d’ère. Unités et tourelles diffèrent : comparez les descriptions.", "Scegli una variante dell’era. Unità e torri sono diverse: confronta le descrizioni.", "Escolhe uma variante da era. Unidades e torres são diferentes; compara as descrições.", "Обери варіант епохи. У них різні бійці й вежі — порівняй описи перед вибором.", "Kies een tijdperkvariant. Troepen en torens verschillen; vergelijk de beschrijvingen.", "Bir çağ çeşidi seç. Birimleri ve kuleleri farklıdır; önce açıklamaları karşılaştır."),
        "hint_weather54" to t("Ikona obok minimapy pokazuje pogodę. Deszcz, wiatr i noc wpływają na walkę; przy wietrze sprawdź strzałkę.", "The icon by the minimap shows weather. Rain, wind and night affect combat; check the wind arrow.", "Das Symbol an der Minikarte zeigt das Wetter. Regen, Wind und Nacht ändern den Kampf; beachte den Windpfeil.", "El icono del minimapa indica el clima. Lluvia, viento y noche afectan el combate; mira la flecha.", "L’icône près de la minicarte indique la météo. Pluie, vent et nuit influent sur le combat; voyez la flèche.", "L’icona sulla minimappa indica il meteo. Pioggia, vento e notte cambiano lo scontro; guarda la freccia.", "O ícone do minimapa mostra o clima. Chuva, vento e noite afetam o combate; vê a seta.", "Піктограма біля мінікарти показує погоду. Дощ, вітер і ніч впливають на бій; дивись стрілку.", "Het pictogram bij de minimap toont het weer. Regen, wind en nacht beïnvloeden de strijd; zie de pijl.", "Mini harita yanındaki simge havayı gösterir. Yağmur, rüzgâr ve gece savaşı etkiler; oka bak."),
    /** Teksty szybkiej pauzy; osobna część ogranicza konflikty tabeli językowej. */
    )

