    /** Zlecenie 93: polityka offline i usuwanie danych rankingu. */
    private fun part93(): Array<Pair<String, Array<out String>>> = arrayOf(
        "privacy93_title" to t("Prywatność — skrót", "Privacy — summary", "Datenschutz — Kurzinfo", "Privacidad — resumen", "Confidentialité — résumé", "Privacy — riepilogo", "Privacidade — resumo", "Приватність — коротко", "Privacy — samenvatting", "Gizlilik — özet"),
        "privacy93_intro" to t("To informacje dostępne offline, a nie pełna opublikowana polityka prywatności.", "This offline summary is not the complete published privacy policy.", "Diese Offline-Übersicht ersetzt nicht die vollständige veröffentlichte Datenschutzerklärung.", "Este resumen sin conexión no sustituye a la política de privacidad completa publicada.", "Ce résumé hors ligne ne remplace pas la politique de confidentialité complète publiée.", "Questo riepilogo offline non sostituisce l'informativa sulla privacy completa pubblicata.", "Este resumo offline não substitui a política de privacidade completa publicada.", "Цей офлайн-огляд не замінює повну опубліковану політику приватності.", "Deze offline samenvatting vervangt niet het volledige gepubliceerde privacybeleid.", "Bu çevrimdışı özet, yayımlanmış tam gizlilik politikasının yerine geçmez."),
        "privacy93_local" to t("Gra przechowuje na urządzeniu pseudonim, postęp, ustawienia i lokalne raporty awarii. Kopia Androida może zawierać profil.", "The game stores your nickname, progress, settings and local crash reports on your device. Android backup may include the profile.", "Das Spiel speichert Namen, Fortschritt, Einstellungen und lokale Absturzberichte auf dem Gerät. Android-Backups können das Profil enthalten.", "El juego guarda apodo, progreso, ajustes e informes de fallos locales en el dispositivo. La copia de Android puede incluir el perfil.", "Le jeu stocke pseudo, progression, réglages et rapports de plantage locaux sur l'appareil. La sauvegarde Android peut inclure le profil.", "Il gioco salva nome, progressi, impostazioni e rapporti di errore locali sul dispositivo. Il backup Android può includere il profilo.", "O jogo guarda nome, progresso, definições e relatórios locais de falhas no dispositivo. O backup Android pode incluir o perfil.", "Гра зберігає псевдонім, прогрес, налаштування та локальні звіти про збої на пристрої. Резервна копія Android може містити профіль.", "De game bewaart naam, voortgang, instellingen en lokale crashrapporten op het toestel. Android-back-ups kunnen het profiel bevatten.", "Oyun takma adı, ilerlemeyi, ayarları ve yerel çökme raporlarını cihazda tutar. Android yedeği profili içerebilir."),
        "privacy93_google" to t("Jeśli działają Usługi Gier Play, Google może przetwarzać tożsamość gracza, wyniki, zapis w chmurze i dane diagnostyczne SDK.", "When Play Games is active, Google may process player identity, scores, cloud saves and SDK diagnostics.", "Bei aktivierten Play-Spielen kann Google Spielerkennung, Ergebnisse, Cloud-Spielstände und SDK-Diagnose verarbeiten.", "Si Play Juegos está activo, Google puede tratar la identidad, las puntuaciones, las partidas en la nube y diagnósticos del SDK.", "Si Play Jeux est actif, Google peut traiter l'identité du joueur, les scores, les sauvegardes cloud et les diagnostics du SDK.", "Se Play Giochi è attivo, Google può trattare identità, punteggi, salvataggi cloud e diagnostica SDK.", "Com Play Jogos ativo, a Google pode tratar identidade, pontuações, gravações na nuvem e diagnósticos do SDK.", "Коли Play Ігри активні, Google може обробляти дані профілю, результати, хмарні збереження та діагностику SDK.", "Als Play Games actief is, kan Google identiteit, scores, cloudopslag en SDK-diagnostiek verwerken.", "Play Oyunlar etkinse Google oyuncu kimliği, puanlar, bulut kayıtları ve SDK tanılama verilerini işleyebilir."),
        "privacy93_server" to t("Po osobnej zgodzie opcjonalny ranking wydawcy może otrzymać przez HTTPS identyfikator, pseudonim, wynik i powtórkę do weryfikacji. Nick i wynik mogą być publiczne.", "With separate consent, the optional publisher leaderboard may receive an ID, nickname, score and replay over HTTPS for verification. Your name and score may be public.", "Mit gesonderter Zustimmung erhält die optionale Rangliste des Anbieters per HTTPS Kennung, Namen, Ergebnis und Wiederholung zur Prüfung. Name und Ergebnis können öffentlich sein.", "Con consentimiento aparte, la clasificación opcional del editor puede recibir ID, apodo, puntuación y repetición por HTTPS. Nombre y puntuación pueden ser públicos.", "Avec accord séparé, le classement facultatif de l'éditeur peut recevoir ID, pseudo, score et replay via HTTPS pour vérification. Pseudo et score peuvent être publics.", "Con consenso separato, la classifica facoltativa dell'editore può ricevere ID, nome, punteggio e replay tramite HTTPS. Nome e punteggio possono essere pubblici.", "Com consentimento separado, o ranking opcional do editor pode receber ID, nome, pontuação e repetição via HTTPS. Nome e pontuação podem ser públicos.", "За окремою згодою рейтинг видавця може отримувати через HTTPS ID, псевдонім, результат і повтор для перевірки. Псевдонім і результат можуть бути публічними.", "Met aparte toestemming kan het optionele klassement via HTTPS ID, naam, score en herhaling ontvangen ter controle. Naam en score kunnen openbaar zijn.", "Ayrı izinle isteğe bağlı yayıncı sıralaması, doğrulama için HTTPS üzerinden kimlik, ad, puan ve tekrar alabilir. Ad ve puan herkese açık olabilir."),
        "privacy93_remove" to t("Opcja usunięcia danych rankingu wydawcy zapisuje żądanie i ponawia je offline. Zapis żądania nie potwierdza jeszcze usunięcia z serwera.", "Deleting publisher leaderboard data stores a request that retries offline. Saving the request does not yet confirm deletion on the server.", "Die Löschung von Ranglistendaten wird gespeichert und offline erneut versucht. Das Speichern bestätigt noch keine Serverlöschung.", "La solicitud de borrado del ranking se guarda y se reintenta sin conexión. Guardarla no confirma aún el borrado en el servidor.", "La demande de suppression du classement est enregistrée et relancée hors ligne. Son enregistrement ne confirme pas encore la suppression du serveur.", "La richiesta di eliminazione della classifica viene salvata e ritentata offline. Il salvataggio non conferma ancora la cancellazione sul server.", "O pedido de eliminação do ranking é guardado e repetido offline. Guardá-lo não confirma a eliminação no servidor.", "Запит на видалення даних рейтингу зберігається й повторюється офлайн. Збереження запиту ще не означає видалення на сервері.", "Een verwijderverzoek voor het klassement wordt bewaard en offline opnieuw geprobeerd. Opslag bevestigt nog geen serververwijdering.", "Sıralama verisi silme isteği kaydedilir ve çevrimdışıyken yeniden denenir. Kayıt, sunucuda silindiği anlamına gelmez."),
        "privacy93_summary_note" to t("Dane lokalne usuń przez ustawienia Androida. Dane Gier Play usuwa się osobno w ustawieniach konta Google.", "Clear local data in Android settings. Delete Play Games data separately in your Google account settings.", "Lokale Daten in den Android-Einstellungen löschen. Play-Spiele-Daten separat im Google-Konto löschen.", "Borra los datos locales en los ajustes de Android. Los datos de Play Juegos se borran por separado en tu cuenta de Google.", "Effacez les données locales dans Android. Les données Play Jeux se suppriment séparément dans les paramètres du compte Google.", "Cancella i dati locali dalle impostazioni Android. Elimina i dati Play Giochi separatamente dall'account Google.", "Apaga os dados locais nas definições Android. Elimina os dados do Play Jogos em separado na conta Google.", "Локальні дані видаляються в налаштуваннях Android. Дані Play Ігор видаляйте окремо в налаштуваннях Google.", "Wis lokale gegevens via Android-instellingen. Verwijder Play Games-gegevens apart via je Google-account.", "Yerel verileri Android ayarlarından silin. Play Oyunlar verilerini Google hesap ayarlarından ayrı silin."),
        "privacy93_delete" to t("Usuń moje dane z rankingu", "Delete my leaderboard data", "Meine Ranglistendaten löschen", "Borrar mis datos del ranking", "Supprimer mes données du classement", "Elimina i miei dati classifica", "Eliminar os meus dados do ranking", "Видалити мої дані рейтингу", "Mijn klassementgegevens wissen", "Sıralama verilerimi sil"),
        "privacy93_confirm" to t("Potwierdź usunięcie", "Confirm deletion", "Löschung bestätigen", "Confirmar borrado", "Confirmer la suppression", "Conferma eliminazione", "Confirmar eliminação", "Підтвердити видалення", "Verwijderen bevestigen", "Silmeyi onayla"),
        "privacy93_saving_short" to t("Zapisuję żądanie…", "Saving request…", "Anfrage wird gespeichert…", "Guardando solicitud…", "Enregistrement…", "Salvataggio richiesta…", "A guardar pedido…", "Збереження запиту…", "Verzoek opslaan…", "İstek kaydediliyor…"),
        "privacy93_delete_hint" to t("Usuwanie dotyczy tylko rankingu wydawcy, nie Gier Play.", "Deletion covers only the publisher ranking, not Play Games.", "Löschung gilt nur für die Verlagsrangliste, nicht für Play Spiele.", "Solo se borra el ranking del editor, no Play Juegos.", "Suppression du classement de l'éditeur, pas de Play Jeux.", "Eliminazione solo per la classifica dell'editore, non Play Giochi.", "Eliminação apenas do ranking do editor, não do Play Jogos.", "Видалення стосується рейтингу видавця, а не Play Ігор.", "Alleen het uitgeversklassement, niet Play Games.", "Yalnızca yayıncı sıralaması silinir; Play Oyunlar değil."),
        "privacy93_no_data" to t("Brak danych tego rankingu na urządzeniu.", "No publisher ranking identity on this device.", "Keine Ranglistenkennung auf diesem Gerät.", "No hay identidad de ranking en este dispositivo.", "Aucun identifiant de classement sur cet appareil.", "Nessuna identità classifica sul dispositivo.", "Sem identidade do ranking neste dispositivo.", "На пристрої немає ID рейтингу видавця.", "Geen klassement-ID op dit toestel.", "Bu cihazda sıralama kimliği yok."),
        "privacy93_unavailable" to t("Serwer rankingu nie jest skonfigurowany. Sprawdź dane Gier Play osobno.", "Leaderboard server is not configured. Manage Play Games data separately.", "Ranglistenserver nicht eingerichtet. Play-Spiele-Daten separat verwalten.", "Servidor de ranking no configurado. Gestiona Play Juegos aparte.", "Serveur de classement non configuré. Gérez Play Jeux séparément.", "Server classifica non configurato. Gestisci Play Giochi separatamente.", "Servidor do ranking não configurado. Gere Play Jogos em separado.", "Сервер рейтингу не налаштовано. Керуйте даними Play Ігор окремо.", "Klassementserver niet ingesteld. Beheer Play Games apart.", "Sıralama sunucusu ayarlı değil. Play Oyunlar verilerini ayrı yönetin."),
        "privacy93_confirm_body" to t("Dotknij ponownie w ciągu 8 sekund, aby zlecić usunięcie danych.", "Tap again within 8 seconds to request deletion of your data.", "Innerhalb von 8 Sekunden erneut tippen, um die Löschung zu beantragen.", "Pulsa otra vez en 8 segundos para solicitar el borrado.", "Appuyez à nouveau sous 8 secondes pour demander la suppression.", "Tocca di nuovo entro 8 secondi per richiedere l'eliminazione.", "Toque novamente em 8 segundos para pedir a eliminação.", "Натисніть ще раз протягом 8 секунд для запиту на видалення.", "Tik opnieuw binnen 8 seconden om verwijdering te vragen.", "Silme istemek için 8 saniye içinde tekrar dokunun."),
        "privacy93_saving" to t("Trwa zapisywanie żądania usunięcia…", "Saving deletion request…", "Löschanfrage wird gespeichert…", "Guardando solicitud de borrado…", "Enregistrement de la demande de suppression…", "Salvataggio richiesta di eliminazione…", "A guardar pedido de eliminação…", "Збереження запиту на видалення…", "Verwijderverzoek opslaan…", "Silme isteği kaydediliyor…"),
        "privacy93_queued" to t("Żądanie zapisane; usunięcie na serwerze nie jest jeszcze potwierdzone.", "Request queued; server deletion is still pending.", "Anfrage gespeichert; Serverlöschung steht noch aus.", "Solicitud en cola; el borrado del servidor aún está pendiente.", "Demande enregistrée ; suppression du serveur en attente.", "Richiesta in coda; eliminazione dal server ancora in sospeso.", "Pedido em fila; eliminação no servidor ainda pendente.", "Запит у черзі; видалення на сервері ще очікується.", "Verzoek in wachtrij; serververwijdering volgt nog.", "İstek sırada; sunucuda silme işlemi henüz bekliyor."),
